const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Point([75.1, 26.9]).buffer(15000); // 15km radius

  const date1Start = '2018-09-15';
  const date1End = '2018-10-15';
  const date2Start = '2019-03-26';
  const date2End = '2019-04-25';

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 3. MNDWI calculation (Green - SWIR) / (Green + SWIR)
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // 4. Data Acquisition - September 2018
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(date1Start, date1End)
    .map(maskS2clouds)
    .map(addMNDWI);

  const size1 = col1.size().getInfo();
  console.log(`Sept 2018 Images: ${size1}`);

  if (size1 === 0) {
    // Fallback to Landsat 8
    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeSambhar)
      .filterDate(date1Start, date1End)
      .map(function(img) {
        const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
        return img.addBands(mndwi);
      });

    const size1_l8 = col1.size().getInfo();
    console.log(`Sept 2018 Landsat Images: ${size1_l8}`);

    if (size1_l8 === 0) {
      console.log("No data for Sept 2018.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 5. Data Acquisition - April 2019
  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(date2Start, date2End)
    .map(maskS2clouds)
    .map(addMNDWI);

  const size2 = col2.size().getInfo();
  console.log(`April 2019 Images: ${size2}`);

  if (size2 === 0) {
    // Fallback to Landsat 8
    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeSambhar)
      .filterDate(date2Start, date2End)
      .map(function(img) {
        const mndwi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
        return img.addBands(mndwi);
      });

    const size2_l8 = col2.size().getInfo();
    console.log(`April 2019 Landsat Images: ${size2_l8}`);

    if (size2_l8 === 0) {
      console.log("No data for April 2019.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 6. Create composite and detect water
  const img1 = col1.median();
  const img2 = col2.median();

  const water1 = img1.select('MNDWI').gt(0);
  const water2 = img2.select('MNDWI').gt(0);

  // 7. Calculate water extent (pixel counts)
  const stats1 = water1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2 = water2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels1 = stats1.get('MNDWI').getInfo();
  const waterPixels2 = stats2.get('MNDWI').getInfo();

  console.log(`Sept 2018 Water Pixels: ${waterPixels1}`);
  console.log(`April 2019 Water Pixels: ${waterPixels2}`);

  // 8. Validation & Final Answer
  if (waterPixels1 === null || waterPixels2 === null) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (waterPixels1 === 0 && waterPixels2 === 0) {
    console.log("No valid water pixels in either period.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check if water decreased from Sept 2018 to April 2019
  if (waterPixels2 < waterPixels1) {
    console.log("Water extent decreased from Sept 2018 to April 2019.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not decrease.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
